"""HKS-double guards for native production placement source chunks."""
from __future__ import annotations
from civ6_host.runtime.provenance import historical_source_file as _historical_source_file, historical_module_file as _historical_module_file, worker_path as _worker_path, pin_key as _pin_key, installed_source_pins as _installed_source_pins
from civ6_host.runtime.resource_resolution import resolve_path as _resolve_resource_path

def guard_case() -> bytes:
    """Embed the actual placement catalog, request and effect source builders.

    The Lua doubles expose parameter shape and fail-closed behavior; they do
    not implement placement rules or stand in for the native legality calls.
    """
    from civ6_host.runtime.native.native_production_placement import catalog_source
    from civ6_host.runtime.native.native_production_placement import choose
    from civ6_host.runtime.native.native_production_placement import effect_source
    from civ6_host.runtime.native.native_production_placement import parse_catalog
    from civ6_host.runtime.native.native_production_placement import request_source
    expected_catalog = b'placement-v1|0|5|4|catalog|5|7|12|90|13|14|16|17|18|31|4|3|5|building:BUILDING_TEST_WONDER:1:101:place:2:2:0|building:BUILDING_TEST_WONDER:1:101:place:5:1:1|building:BUILDING_TEST_PLACED:2:102:resume:-1:-1:-1|building:BUILDING_TEST_ALREADY:3:103:resume:-1:-1:-1|district:DISTRICT_TEST_PLACE:0:201:place:3:3:0'
    catalog = parse_catalog(expected_catalog, 0, 5, 4)
    choices = (choose(catalog, 'building', 1, 2), choose(catalog, 'building', 2, -1), choose(catalog, 'building', 3, -1), choose(catalog, 'district', 0, 3))
    chunks = ["\nlocal localID,observer,turn,owner,queueSize=0,0,4,0,0\nlocal alive,active,complete=true,true,true\nlocal canVisible,canEnabled,canStart=true,true,true\nlocal submitCount,targetCalls,plotReads=0,0,{}\nlocal targetMode='valid'\nlocal placed={[102]=true}\nlocal hasBuilding={[103]=true}\nlocal rowsBuilding={\n {BuildingType='BUILDING_TEST_WONDER',Index=1,Hash=101,RequiresPlacement=true,IsWonder=true},\n {BuildingType='BUILDING_TEST_PLACED',Index=2,Hash=102,RequiresPlacement=true,IsWonder=true},\n {BuildingType='BUILDING_TEST_ALREADY',Index=3,Hash=103,RequiresPlacement=true,IsWonder=true},\n}\nlocal rowsDistrict={\n {DistrictType='DISTRICT_TEST_PLACE',Index=0,Hash=201,RequiresPlacement=true},\n {DistrictType='DISTRICT_TEST_INTERNAL',Index=1,Hash=202,RequiresPlacement=true,InternalOnly=true},\n}\nlocal function info(rows,field)\n local t={}\n for _,r in ipairs(rows) do t[r[field]]=r;t[r.Index]=r end\n return setmetatable(t,{__call=function() local i=0;return function()\n  i=i+1;return rows[i]\n end end})\nend\nlocal GameInfo={Buildings=info(rowsBuilding,'BuildingType'),Districts=info(rowsDistrict,'DistrictType'),\n Units=info({},'UnitType'),Projects=info({},'ProjectType')}\nlocal Game={GetLocalPlayer=function() return localID end,\n GetLocalObserver=function() return observer end,GetCurrentGameTurn=function() return turn end}\nlocal cityBuildings={\n HasBuilding=function(_,hash)\n  assert(hash==101 or hash==103,'unexpected HasBuilding identity')\n  return hasBuilding[hash] or false\n end,\n IsPillaged=function() return false end,\n}\nlocal queue={\n GetSize=function() return queueSize end,\n CanProduce=function(_,input,visibility,details)\n  assert(type(input)=='number')\n  if visibility then assert(details==nil);return canVisible end\n  assert(visibility==false and details==true);return canEnabled,{}\n end,\n HasBeenPlaced=function(_,hash) return placed[hash] or false end,\n}\nlocal city={GetID=function() return 5 end,GetOwner=function() return owner end,\n GetBuildQueue=function() return queue end,GetBuildings=function() return cityBuildings end}\nlocal player={IsAlive=function() return alive end,IsTurnActive=function() return active end,\n IsTurnActiveComplete=function() return complete end,\n GetCities=function() return {Members=function() local done=false;return function()\n  if not done then done=true;return 1,city end\n end end} end}\nlocal Players={[0]=player}\nlocal revealed={[0]=true,[1]=true,[2]=true,[3]=true,[4]=true,[5]=true,[6]=true,\n [7]=false,[8]=true,[9]=true,[10]=true,[11]=true}\nlocal PlayersVisibility={[0]={IsRevealed=function(_,id) return revealed[id] or false end}}\nlocal function makePlot(id)\n return {GetIndex=function() return id end,GetX=function() return id%4 end,\n  GetY=function() return math.floor(id/4) end,GetOwner=function() return owner end,\n  GetDistrictType=function() return id==3 and 0 or -1 end,\n  GetWonderType=function() return (id==2 or id==5) and 1 or -1 end}\nend\nlocal Map={GetGridSize=function() return 4,3 end,GetPlotCount=function() return 12 end,\n GetPlotByIndex=function(id)\n  plotReads[id]=(plotReads[id] or 0)+1\n  assert(revealed[id],'hidden plot getter must not be read')\n  return makePlot(id)\n end}\nlocal CityOperationTypes={BUILD=7,PARAM_INSERT_MODE=12,VALUE_REPLACE_AT=90,\n PARAM_QUEUE_DESTINATION_LOCATION=13,PARAM_BUILDING_TYPE=14,PARAM_DISTRICT_TYPE=16,\n PARAM_X=17,PARAM_Y=18,PARAM_UNIT_TYPE=11,PARAM_PROJECT_TYPE=15}\nlocal CityOperationResults={PLOTS=31}\nlocal function countKeys(t) local n=0;for _ in pairs(t) do n=n+1 end;return n end\nlocal function checkOperationArgs(op,args,place,kind,hash)\n assert(op==7)\n local key=kind=='building' and 14 or 16\n assert(args[key]==hash and args[12]==90 and args[13]==0)\n if place then\n  assert(countKeys(args)==5 and args[17]~=nil and args[18]~=nil)\n  assert(args[17]>=0 and args[17]<4 and args[18]>=0 and args[18]<3)\n else\n  assert(countKeys(args)==3 and args[17]==nil and args[18]==nil)\n end\nend\nlocal function targetList(hash)\n if targetMode=='hidden' then return {7} end\n if targetMode=='duplicate' then return {2,2} end\n if targetMode=='sparse' then return {[1]=2,[3]=5} end\n if targetMode=='overbound' then return {2,5,3,4,6,8,9,10,11,0,1,7,2} end\n if hash==101 then return targetMode=='stale' and {5} or {2,5} end\n if hash==201 then return {3} end\n return {}\nend\nlocal CityManager={\n GetOperationTargets=function(c,op,args)\n  targetCalls=targetCalls+1;assert(c==city and op==7 and countKeys(args)==1)\n  assert((args[14]~=nil and args[16]==nil and args[17]==nil and args[18]==nil) or\n         (args[16]~=nil and args[14]==nil and args[17]==nil and args[18]==nil),\n         'target query must be hash-only')\n  local hash=args[14] or args[16];assert(hash==101 or hash==201)\n  return {[31]=targetList(hash)}\n end,\n CanStartOperation=function(c,op,args,details)\n  assert(c==city);local kind=args[14] and 'building' or 'district'\n  local place=args[17]~=nil;assert(details==place)\n  checkOperationArgs(op,args,place,kind,args[14] or args[16]);return canStart\n end,\n RequestOperation=function(c,op,args)\n  assert(c==city);local kind=args[14] and 'building' or 'district'\n  checkOperationArgs(op,args,args[17]~=nil,kind,args[14] or args[16])\n  submitCount=submitCount+1\n end,\n}\nlocal function assertRejected(fn) local before=submitCount;assert(not pcall(fn));assert(submitCount==before) end\n".encode('ascii')]
    chunks.extend([b'local function collect()\n', catalog_source(0, 5, 4), b'\nend\n'])
    for i, choice in enumerate(choices, 1):
        chunks.extend([f'local function request{i}()\n'.encode('ascii'), request_source(choice), b'\nend\n'])
    chunks.extend([b'local function effect1()\n', effect_source(choices[0]), b'\nend\n'])
    expected_lua = "'" + expected_catalog.decode('ascii') + "'"
    chunks.append(('\nlocal expected=' + expected_lua + "\nassert(collect()==expected,'actual placement catalog differs from fixture')\nassert(targetCalls==2,'resume entries must not query target plots')\n-- Same item at two legal plots gives two choices with one item identity.\nassert(request1()=='submitted' and request4()=='submitted' and submitCount==2)\n-- HasBeenPlaced and HasBuilding resume branches never send X/Y.\nassert(request2()=='submitted' and request3()=='submitted' and submitCount==4)\nlocal before=targetCalls;local readsBefore=plotReads[7] or 0\ntargetMode='hidden';assertRejected(collect)\nassert(targetCalls==before+1 and (plotReads[7] or 0)==readsBefore,\n       'unrevealed target reached Map.GetPlotByIndex')\nfor _,bad in ipairs({'duplicate','sparse','overbound'}) do targetMode=bad;assertRejected(collect) end\ntargetMode='valid';local beforeSubmits=submitCount\ntargetMode='stale';assertRejected(request1);assert(submitCount==beforeSubmits);targetMode='valid'\ncanStart=false;assertRejected(request1);canStart=true\n-- CanProduce returns false -> an empty legal catalog, and target enumeration is skipped.\ncanVisible=false;local calls=targetCalls;local veto=collect()\nassert(veto:match('|catalog|5|.*|0$') and targetCalls==calls and submitCount==beforeSubmits)\ncanVisible=true;canEnabled=false;calls=targetCalls;veto=collect()\nassert(veto:match('|catalog|5|.*|0$') and targetCalls==calls and submitCount==beforeSubmits)\ncanEnabled=true\n-- Readiness and city ownership are rechecked by the real request chunk.\nlocalID=1;assertRejected(request1);localID=0\nobserver=1;assertRejected(request1);observer=0\nturn=5;assertRejected(request1);turn=4\nalive=false;assertRejected(request1);alive=true\nactive=false;assertRejected(request1);active=true\ncomplete=false;assertRejected(request1);complete=true\nowner=1;assertRejected(request1);owner=0\nqueueSize=1;assertRejected(request1);queueSize=0\nlocal savedX=CityOperationTypes.PARAM_X;CityOperationTypes.PARAM_X=19\nassertRejected(request1);CityOperationTypes.PARAM_X=savedX\nfor _,name in ipairs({'BUILD','PARAM_BUILDING_TYPE','PARAM_INSERT_MODE',\n 'PARAM_QUEUE_DESTINATION_LOCATION','PARAM_Y'}) do\n local old=CityOperationTypes[name];CityOperationTypes[name]=999\n assertRejected(request1);CityOperationTypes[name]=old\nend\nlocal oldPlots=CityOperationResults.PLOTS;CityOperationResults.PLOTS=999\nassertRejected(request1);CityOperationResults.PLOTS=oldPlots\n-- Native effect readback is placement status, not completion.\nplaced[101]=true\nassert(effect1()=='placement-effect-v1|0|5|4|building|1|101|place|2|2|0|1|1|0')\nreturn 'native-production-placement-guards-ok'\n").encode('ascii'))
    return b''.join(chunks)
